# Check if 3s are always in columns between boundary columns

def predict_output_2d(grid_in):
    bg_out = grid_in[0][0]  # background
    fill_val = 3
    boundary_val = 5
    grid_rows = len(grid_in)
    grid_cols = len(grid_in[0])

    # Find which rows and columns have boundary (5)
    rows_with_5 = set()
    cols_with_5 = set()
    for r in range(grid_rows):
        for c in range(grid_cols):
            if grid_in[r][c] == boundary_val:
                rows_with_5.add(r)
                cols_with_5.add(c)

    result = [[grid_in[r][c] for c in range(grid_cols)] for r in range(grid_rows)]

    # Fill rule: if row has 5 and col has 5, fill with 3 (unless it's a boundary)
    for r in range(grid_rows):
        for c in range(grid_cols):
            if r in rows_with_5 and c in cols_with_5:
                if grid_in[r][c] != boundary_val:
                    result[r][c] = fill_val

    return result

# Verify on Demo 1
print("Verifying 2D hypothesis on Demo 1:")
for i in range(6):
    pred = predict_output_2d(d1_input[i])
    match = pred == d1_output[i]
    print(f"Row {i}: {'✓' if match else '✗'}")
    if not match:
