# Let me test: maybe the 3-fill is the "intersection" of row-gap-conditions and col-gap-conditions

# A row "gaps" if it has 5s with gaps between them
# A column "gaps" if it has 5s with gaps between them

# A cell gets 3 if both its row and column "gap"

def has_gaps_in_row(row):
    bps = [c for c in range(28) if row[c] == 5]
    # Has gaps if at least 2 boundary positions with gap > 0 between
    if len(bps) < 2:
        return False
    for i in range(len(bps) - 1):
        if bps[i+1] - bps[i] > 1:
            return True
    return False

def has_gaps_in_col(col_data):
    # col_data is list of values in order
    bps = [r for r in range(6) if col_data[r] == 5]
    if len(bps) < 2:
        return False
    for i in range(len(bps) - 1):
        if bps[i+1] - bps[i] > 1:
            return True
    return False

print("Row gap analysis:")
