    print(f"  Row {r}: has_gaps={has_gaps_in_row(d1_input[r])}, 5s at {[c for c,v in enumerate(d1_input[r]) if v==5]}")

print("\nCol gap analysis:")
for c in range(28):
    col = [d1_input[r][c] for r in range(6)]
    print(f"  Col {c}: has_gaps={has_gaps_in_col(col)}, 5s at {[r for r,v in enumerate(col) if v==5]}")

